package com.sliide.useractivity.domain.time

import kotlin.time.Clock
import kotlin.time.ExperimentalTime

interface AppClock {
    fun nowMillis(): Long
}

class SystemAppClock : AppClock {
    @OptIn(ExperimentalTime::class)
    override fun nowMillis(): Long = Clock.System.now().toEpochMilliseconds()
}

package com.sliide.useractivity.domain.time

class RelativeTimeFormatter {
    fun format(thenMillis: Long, nowMillis: Long): String {
        val elapsedSeconds = ((nowMillis - thenMillis) / 1_000).coerceAtLeast(0)
        return when {
            elapsedSeconds < 60 -> "Just now"
            elapsedSeconds < 3_600 -> plural(elapsedSeconds / 60, "minute")
            elapsedSeconds < 86_400 -> plural(elapsedSeconds / 3_600, "hour")
            elapsedSeconds < 604_800 -> plural(elapsedSeconds / 86_400, "day")
            elapsedSeconds < 2_592_000 -> plural(elapsedSeconds / 604_800, "week")
            else -> "30+ days ago"
        }
    }

    private fun plural(value: Long, unit: String): String =
        if (value == 1L) "1 $unit ago" else "$value ${unit}s ago"
}

package com.sliide.useractivity.presentation.users

import com.sliide.useractivity.domain.AppResult
import com.sliide.useractivity.domain.model.User
import com.sliide.useractivity.domain.repository.UserRepository
import com.sliide.useractivity.domain.time.AppClock
import com.sliide.useractivity.domain.time.RelativeTimeFormatter

interface LoadUserFeedUseCase {
    suspend operator fun invoke(): AppResult<List<UserFeedItem>>
}

class GetSmartUserFeedUseCase(
    private val userRepository: UserRepository,
    private val clock: AppClock,
    private val relativeTimeFormatter: RelativeTimeFormatter = RelativeTimeFormatter(),
    private val perPage: Int = 20,
) : LoadUserFeedUseCase {
    override suspend fun invoke(): AppResult<List<UserFeedItem>> {
        val firstPageResult = userRepository.getUsers(page = 1, perPage = perPage)
        val firstPage = when (firstPageResult) {
            is AppResult.Success -> firstPageResult.value
            is AppResult.Failure -> return firstPageResult
        }

        val lastPage = firstPage.totalPages.coerceAtLeast(1)
        val finalPage = if (lastPage == firstPage.page) {
            firstPage
        } else {
            when (val lastPageResult = userRepository.getUsers(page = lastPage, perPage = perPage)) {
                is AppResult.Success -> lastPageResult.value
                is AppResult.Failure -> return lastPageResult
            }
        }

        val fetchedAtMillis = clock.nowMillis()
        val users = finalPage.items.map { user -> user.toFeedItem(fetchedAtMillis) }
        return AppResult.Success(users)
    }

    private fun User.toFeedItem(fetchedAtMillis: Long): UserFeedItem = UserFeedItem(
        id = id,
        name = name,
        email = email,
        gender = gender,
        status = status,
        fetchedAtMillis = fetchedAtMillis,
        relativeTimestamp = relativeTimeFormatter.format(
            thenMillis = fetchedAtMillis,
            nowMillis = clock.nowMillis(),
        ),
    )
}

package com.sliide.useractivity.presentation.users

import com.sliide.useractivity.domain.AppError
import com.sliide.useractivity.domain.AppResult
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

class UserFeedViewModel(
    private val loadUserFeed: LoadUserFeedUseCase,
    private val scope: CoroutineScope,
) {
    private val _state = MutableStateFlow(UserFeedState())
    val state: StateFlow<UserFeedState> = _state.asStateFlow()

    fun load() {
        val current = _state.value
        if (current.isLoading || current.users.isNotEmpty()) return
        loadInternal(isRefresh = false)
    }

    fun refresh() {
        val current = _state.value
        if (current.isLoading || current.isRefreshing) return
        loadInternal(isRefresh = current.users.isNotEmpty())
    }

    fun retry() {
        val current = _state.value
        if (current.isLoading || current.isRefreshing) return
        loadInternal(isRefresh = current.users.isNotEmpty())
    }

    private fun loadInternal(isRefresh: Boolean) {
        scope.launch {
            _state.update { current ->
                current.copy(
                    isLoading = !isRefresh,
                    isRefreshing = isRefresh,
                    errorMessage = null,
                    offlineMessage = null,
                    canRetry = false,
                )
            }

            when (val result = loadUserFeed()) {
                is AppResult.Success -> _state.update { current ->
                    current.copy(
                        isLoading = false,
                        isRefreshing = false,
                        users = result.value,
                        errorMessage = null,
                        offlineMessage = null,
                        canRetry = false,
                    )
                }

                is AppResult.Failure -> _state.update { current ->
                    val message = result.error.toUserMessage()
                    val offline = result.error.isOfflineError()
                    current.copy(
                        isLoading = false,
                        isRefreshing = false,
                        errorMessage = if (offline) null else message,
                        offlineMessage = if (offline) message else null,
                        canRetry = true,
                    )
                }
            }
        }
    }

    private fun AppError.isOfflineError(): Boolean = this is AppError.Network || this is AppError.Timeout

    private fun AppError.toUserMessage(): String = when (this) {
        AppError.Network -> "No internet connection. Try again when you are back online."
        AppError.Timeout -> "The connection timed out. Please try again."
        AppError.Unauthorized -> "This request is not authorised."
        AppError.NotFound -> "Users could not be found."
        is AppError.Validation -> message ?: "The request was not valid."
        is AppError.Server -> "The service is unavailable right now. Please try again."
        is AppError.Unknown -> message ?: "Something went wrong. Please try again."
    }
}

