import com.sliide.useractivity.presentation.users.UserFeedState
import com.sliide.useractivity.ui.components.ContentState
import com.sliide.useractivity.ui.components.ContentStateContainer
import com.sliide.useractivity.ui.components.StateMessage
import com.sliide.useractivity.ui.shell.appBodyPaddingValues

@Composable
fun UserFeedScreen(
    state: UserFeedState,
    selectedUserId: Long?,
    onUserClick: (Long) -> Unit,
    onRefresh: () -> Unit,
    onRetry: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val contentState = when {
        state.isLoading -> ContentState.Loading
        state.errorMessage != null && state.users.isEmpty() -> ContentState.Error(state.errorMessage)
        state.offlineMessage != null && state.users.isEmpty() -> ContentState.Error(state.offlineMessage)
        state.isEmpty -> ContentState.Empty
        else -> ContentState.Content
    }

    Column(
        modifier = modifier
            .fillMaxSize()
            .padding(appBodyPaddingValues()),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        if (state.offlineMessage != null && state.users.isNotEmpty()) {
            OfflineMessage(message = state.offlineMessage)
        }
        if (state.errorMessage != null && state.users.isNotEmpty()) {
            InlineErrorMessage(message = state.errorMessage)
        }
        if (state.isRefreshing) {
            Text(
                text = "Refreshing…",
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                style = MaterialTheme.typography.labelMedium,
            )
        }
        ContentStateContainer(
            state = contentState,
            modifier = Modifier.fillMaxSize(),
            emptyTitle = "No users yet",
            emptyBody = "Refresh to check the latest GoREST users.",
            emptyActionLabel = "Refresh",
            onEmptyAction = onRefresh,
            errorTitle = if (state.offlineMessage != null) "No internet" else "Could not load users",
            onRetry = if (state.canRetry) onRetry else null,
            loadingRows = 8,
        ) {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                state.users.forEach { user ->
                    UserFeedRow(
                        user = user,
                        selected = user.id == selectedUserId,
                        onClick = { onUserClick(user.id) },
                    )
                }
            }
        }
    }
}

@Composable
private fun OfflineMessage(message: String) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        color = MaterialTheme.colorScheme.surfaceVariant,
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
    ) {
        Text(
            text = message,
            modifier = Modifier.padding(10.dp),
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            style = MaterialTheme.typography.bodySmall,
        )
    }
}

@Composable
private fun InlineErrorMessage(message: String) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        color = MaterialTheme.colorScheme.error.copy(alpha = 0.08f),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.error.copy(alpha = 0.35f)),
    ) {
        Text(
            text = message,
            modifier = Modifier.padding(10.dp),
            color = MaterialTheme.colorScheme.error,
            style = MaterialTheme.typography.bodySmall,
        )
    }
}

